import { NextResponse } from "next/server";
import { readFile } from "fs/promises";
import path from "path";

/**
 * Live repository statistics — serves the same data the extension's GitHub
 * Pages site renders (docs/stats.json), generated by scripts/update-stats.mjs.
 */

let cache: { at: number; data: unknown } | null = null;
const TTL_MS = 60_000;

export async function GET() {
  try {
    if (cache && Date.now() - cache.at < TTL_MS) {
      return NextResponse.json(cache.data);
    }
    const raw = await readFile(path.join(process.cwd(), "db", "stats.json"), "utf-8");
    const data = JSON.parse(raw);
    cache = { at: Date.now(), data };
    return NextResponse.json(data);
  } catch (error) {
    console.error("GET /api/stats failed:", error);
    return NextResponse.json({ error: "Stats unavailable" }, { status: 503 });
  }
}
